async function render(route){const version=++renderVersion;current=route;
 if(route!=='AI settings')clearTimeout(aiPollTimer);
 if(route.startsWith('invite=')){authPage(true);return;}
 if(route==='Signup'&&!user){await signupPage();return;}
 if(!user){authPage(false);return;}
 root.innerHTML=shell(`<section class="panel live-workspace-loading">${loadingMarkup('Opening your workspace','Loading your saved documents, preferences and applications.')}<div class="skeleton-grid"><span></span><span></span><span></span></div></section>`);applyTheme();
 try{
  await loadSession();let content,a;if(route==='Job toolkit'||route.startsWith('Job toolkit/')||route==='Writing'||route.startsWith('Writing/'))exportTemplates=(await api('/exports/templates')).templates;
  if(route==='Today')content=today();
  else if(route==='AI settings')content=aiSettingsPage(await api('/ai/status'));
  else if(route==='Search settings'){if(user.role!=='admin')throw Error('Administrator access is required.');content=searchSettingsPage(await api('/admin/search'));}
  else if(route==='Job toolkit'||route.startsWith('Job toolkit/')){if(route.includes('/')){toolkitJob=applications.find(a=>a.id===route.split('/')[1])||null;toolkitData=null;}if(toolkitJob?.description)toolkitData=await api('/toolkit','POST',{action:'load',job:toolkitJob});content=toolkitPage(await api('/ai/status'));}
  else if(route==='Applications')content=listPage();
  else if(route==='Analytics')content=analyticsPage(await api('/analytics?days='+analyticsDays));
  else if(route==='Opportunities'){if(!searchInitialized)useSearchPreferences();const [providers,recommendations]=await Promise.all([api('/jobs/providers'),api('/jobs/recommendations')]);roleRecommendations=recommendations;content=jobSearchPage(providers);}
  else if(route==='New application')content=editor(jobDraft||{});
  else if(route.startsWith('Application/')){const data=await api('/applications/'+route.split('/')[1]);a=data.application;content=editor(a,data.history);}
  else if(route==='Role preferences')content=preferencesPage();
  else if(route==='CV studio')content=cvPage(await api('/cv'));
  else if(route==='Writing'||route.startsWith('Writing/')){a=route.includes('/')?applications.find(j=>j.id===route.split('/')[1]):applications[0];if(route.includes('/')&&!a)throw Error('Application not found.');const data=a?await api('/applications/'+a.id+'/letter'):{letter:null};content=writingPage(a,data.letter);}
  else if(route==='My account')content=accountPage();else if(route==='Email sync')content=emailConnectionsPage(await api('/email'));else if(route.startsWith('Interview/')){a=applications.find(j=>j.id===route.split('/')[1]);if(!a)throw Error('Save this job first.');content=interviewPage(await api('/interview','POST',{job:a}));}
  else if(['Members','Invitations'].includes(route)){if(user.role!=='admin')throw Error('Administrator access is required.');const data=await api('/admin/'+(route==='Members'?'members':'invitations'));content=adminPage(data.members||[],data.invitations||[]);}
  else {navigate('Today');return;}
  if(version!==renderVersion)return;root.innerHTML=shell(content);applyTheme();document.title='Milo · '+route.split('/')[0];bindPage(route,a);window.scrollTo(0,0);
  if(route==='Opportunities'&&!searchResults){
   if(!searchSettings.query.trim()){const recommendations=roleRecommendations||await api('/jobs/recommendations');if(version!==renderVersion)return;if(recommendations.available&&recommendations.roles.length){searchSettings.query=recommendations.roles.join(', ');document.querySelector('#search-keywords').value=searchSettings.query;}}
   if(searchSettings.query.trim())await searchJobs(1,searchSettings);
  }
 }catch(error){if(version!==renderVersion)return;if(!user)authPage();else root.innerHTML=shell(heading('Unable to open this page.',error.message,button('Back to today','Today')));applyTheme();notify(error.message);}
}
document.addEventListener('click',async e=>{try{
 const exportButton=e.target.closest('[data-export-format]');if(exportButton){await downloadExport(exportButton);return;}
 const suggestion=e.target.closest('[data-suggested-role]');if(suggestion){const role=roleRecommendations?.suggestions[Number(suggestion.dataset.suggestedRole)]?.role;if(role){document.querySelector('#search-keywords').value=role;await searchJobs();}return;}
 const copied=e.target.closest('[data-copy-email-redirect]');if(copied){const field=document.querySelector('#email-'+copied.dataset.copyEmailRedirect+'-redirect');try{await navigator.clipboard.writeText(field.value);notify('Redirect URL copied.');}catch{field.focus();field.select();notify('Select and copy this redirect URL.');}return;}
 const workspace=e.target.closest('[data-email-workspace]');if(workspace){await api('/email/settings','PUT',{provider:workspace.dataset.emailWorkspace,useWorkspace:true});await render('Email sync');notify('Personal app configuration removed.');return;}
 const emailConnect=e.target.closest('[data-email-connect]');if(emailConnect){if(emailConnect.dataset.configured!=='true'){const key=emailConnect.dataset.emailConnect.toLowerCase(),setup=document.querySelector('#email-'+key+'-setup');setup.open=true;setup.scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('#email-'+key+'-client').focus();return;}emailConnect.disabled=true;try{const result=await api('/email/connect','POST',{provider:emailConnect.dataset.emailConnect});window.location.assign(result.url);}catch(error){emailConnect.disabled=false;throw error;}return;}
 const emailSync=e.target.closest('[data-email-sync]');if(emailSync){emailSync.disabled=true;const status=document.querySelector('#email-'+emailSync.dataset.emailSync.toLowerCase()+'-status');status.textContent='Syncing job-related emails…';try{const result=await api('/email/sync','POST',{provider:emailSync.dataset.emailSync});await render('Email sync');notify(result.imported+' messages reviewed.');}catch(error){status.textContent=error.message;throw error;}finally{emailSync.disabled=false;}return;}
 const emailDisconnect=e.target.closest('[data-email-disconnect]');if(emailDisconnect){await api('/email/disconnect','POST',{provider:emailDisconnect.dataset.emailDisconnect});await render('Email sync');return;}
 const recommended=e.target.closest('[data-cv-recommend]');if(recommended){recommended.disabled=true;try{const data=roleRecommendations||await api('/jobs/recommendations');if(!data.available||!data.roles.length)throw Error('Upload a readable CV or cover letter, or enter a target role.');document.querySelector('#search-keywords').value=data.roles.join(', ');notify('Suggested search: '+data.roles.join(', '));await searchJobs();}finally{recommended.disabled=false;}return;}
 const saved=e.target.closest('[data-save-job]');if(saved){saved.disabled=true;try{const job=searchResults?.jobs[Number(saved.dataset.saveJob)];if(!job)throw Error('Search again to select a job.');await saveListing(job);saved.textContent='Saved';notify('Job saved to Applications.');}catch(error){saved.disabled=false;throw error;}return;}
 const preparation=e.target.closest('[data-interview-job]');if(preparation){const job=searchResults?.jobs[Number(preparation.dataset.interviewJob)];if(!job)throw Error('Search again to select a job.');const app=await saveListing(job);navigate('Interview/'+app.id);return;}
 if(e.target.closest('[data-toolkit-interview]')){const target=document.querySelector('#interview-plan');target.textContent='Preparing study plan…';const plan=await api('/interview','POST',{job:currentToolkitJob()});target.innerHTML=interviewPage(plan);return;}
 if(!e.target.closest('.nav-dropdown'))document.querySelectorAll('.nav-dropdown[open]').forEach(menu=>menu.open=false);
 const providerCard=e.target.closest('[data-provider-choice]');if(providerCard){const field=document.querySelector('#ai-provider');field.value=providerCard.dataset.providerChoice;field.dispatchEvent(new Event('change'));}
 const aiLogin=e.target.closest('[data-ai-login]');if(aiLogin){aiLogin.disabled=true;try{const state=await api('/ai/login','POST',{});document.querySelector('#ai-account-status').innerHTML=accountConnection(state);pollAIAccount();}finally{aiLogin.disabled=false;}}
 if(e.target.closest('[data-ai-disconnect]')){await api('/ai/logout','POST',{});await render('AI settings');}
 const toolAction=e.target.closest('[data-toolkit-action]');if(toolAction)await toolkitAction(toolAction.dataset.toolkitAction);
 const jobTools=e.target.closest('[data-job-tools]');if(jobTools){toolkitJob=searchResults?.jobs[Number(jobTools.dataset.jobTools)]||null;toolkitData=null;navigate('Job toolkit');}
 const download=e.target.closest('[data-toolkit-download]');if(download){const isCV=download.dataset.toolkitDownload==='cv',contents=value(isCV?'toolkit-cv':document.querySelector('#toolkit-letter')?'toolkit-letter':'letter-text');if(!contents.trim())throw Error('Generate or write a draft first.');const url=URL.createObjectURL(new Blob([contents],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=isCV?'Milo-tailored-CV.txt':'Milo-custom-cover-letter.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const usePreferences=e.target.closest('[data-use-search-preferences]');if(usePreferences){document.querySelector('#search-keywords').value=preferences.titles;document.querySelector('#search-location').value=preferences.location;document.querySelector('#search-remote').checked=preferences.workplace==='Remote';document.querySelector('#search-provider').value='All available';document.querySelector('#company-search-options').hidden=true;document.querySelector('#search-board-help').hidden=false;searchResults=null;await searchJobs();}
 const page=e.target.closest('[data-job-page]');if(page)await searchJobs(searchSettings.page+(page.dataset.jobPage==='next'?1:-1));
 const imported=e.target.closest('[data-import-job]');if(imported){const job=searchResults?.jobs[Number(imported.dataset.importJob)];if(!job)throw Error('Search again to select this job.');const existing=applications.find(a=>a.url===job.url);if(existing){navigate('Application/'+existing.id);notify('This job is already saved.');}else{jobDraft={country:searchSettings.country,role:job.role,company:job.company,location:job.location,url:job.url,source:job.source,description:job.description,workplace:job.remote===true?'Remote':'Onsite',employment_type:job.employment_type||'Permanent',stage:'Discovered',salary:null,notes:'Imported from '+job.source+'. Verify work arrangement, employment type, salary and location eligibility before applying.'};navigate('New application');}}
 const themeButton=e.target.closest('[data-theme-toggle]');if(themeButton){theme=theme==='dark'?'light':'dark';try{localStorage.setItem('milo-theme',theme);}catch{}applyTheme();}
 const route=e.target.closest('[data-route]');if(route){e.preventDefault();navigate(route.dataset.route);}
 if(e.target.closest('[data-logout]')){const invitation=location.hash.startsWith('#invite=');await api('/logout','POST',{});user=null;jobDraft=null;searchResults=null;searchInitialized=false;toolkitJob=null;toolkitData=null;toolkitContext={tone:'Professional',evidence:'',motivation:''};clearTimeout(aiPollTimer);if(!invitation)history.replaceState(null,'','#Login');authPage(invitation);}
 const revoke=e.target.closest('[data-revoke-invitation]');if(revoke&&window.confirm('Revoke this invitation?')){await api('/admin/invitations/'+revoke.dataset.revokeInvitation,'DELETE',{});await render('Invitations');notify('Invitation revoked.');}
 const remove=e.target.closest('[data-delete-document]');if(remove&&window.confirm('Permanently remove this uploaded file?')){const typed=document.querySelector('#cv-text')?.value;await api('/documents/'+remove.dataset.deleteDocument,'DELETE',{});await render('CV studio');if(typed!==undefined)document.querySelector('#cv-text').value=typed;notify('File removed.');}
 if(e.target.closest('[data-download-letter]')){const contents=value('letter-text');if(!contents.trim())throw Error('Write a letter first.');const url=URL.createObjectURL(new Blob([contents],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='Milo-cover-letter.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 }catch(error){notify(error.message);}
});
function routeFromHash(){try{return decodeURIComponent(location.hash.slice(1))||'Today';}catch{return 'Today';}}
window.addEventListener('hashchange',()=>render(routeFromHash()));
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.nav-dropdown[open]').forEach(menu=>{menu.open=false;menu.querySelector('summary')?.focus();});});
(async()=>{applyTheme();try{await loadSession();}catch(error){if(error.status!==401)notify(error.message);}await render(routeFromHash());})();
